cssCode:
.visualizer {
  display: flex; gap: 8px; align-items: center; justify-content: center;
  height: 80px;
}
.bar {
  width: 12px; background: linear-gradient(to top, #9d50bb, #6e48aa);
  border-radius: 6px;
  animation: bounceAudio 1.2s ease-in-out infinite alternate;
  box-shadow: 0 0 10px #9d50bb;
}
@keyframes bounceAudio {
  0% { height: 10px; }
  100% { height: 70px; }
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';
const vis = document.createElement('div');
vis.className = 'visualizer';

const delays = ['0s', '0.2s', '0.4s', '0.1s', '0.5s'];
for(let i=0; i<5; i++) {
  const bar = document.createElement('div');
  bar.className = 'bar';
  bar.style.animationDelay = delays[i];
  vis.appendChild(bar);
}
c.appendChild(vis);
